package auth

import (
 "context"; "crypto/rsa"; "encoding/base64"; "encoding/json"; "errors"; "math/big"; "net/http"; "sync"; "time"
 "github.com/golang-jwt/jwt/v5"
)
type Validator struct { issuer,audience,jwksURL string; client *http.Client; mu sync.RWMutex; keys map[string]*rsa.PublicKey; refreshed time.Time }
type jwks struct { Keys []struct { Kid,Kty,Alg,N,E string } `json:"keys"` }
func New(issuer,audience,url string)*Validator{return &Validator{issuer:issuer,audience:audience,jwksURL:url,client:&http.Client{Timeout:5*time.Second},keys:map[string]*rsa.PublicKey{}}}
func (v *Validator) Validate(ctx context.Context, raw string)(string,error){ if err:=v.refresh(ctx,false);err!=nil{return "",err}; token,err:=jwt.Parse(raw,func(t *jwt.Token)(any,error){if t.Method.Alg()!="RS256" {return nil,errors.New("unsupported signing algorithm")};kid,_:=t.Header["kid"].(string);v.mu.RLock();key:=v.keys[kid];v.mu.RUnlock();if key==nil {if err:=v.refresh(ctx,true);err!=nil{return nil,err};v.mu.RLock();key=v.keys[kid];v.mu.RUnlock()};if key==nil{return nil,errors.New("unknown key")};return key,nil},jwt.WithIssuer(v.issuer),jwt.WithAudience(v.audience),jwt.WithValidMethods([]string{"RS256"}),jwt.WithExpirationRequired(),jwt.WithIssuedAt());if err!=nil||!token.Valid{return "",errors.New("invalid token")};claims,ok:=token.Claims.(jwt.MapClaims);if !ok{return "",errors.New("invalid claims")};sub,ok:=claims["sub"].(string);if !ok||sub==""{return "",errors.New("missing subject")};return sub,nil }
func(v *Validator)refresh(ctx context.Context,force bool)error{v.mu.RLock();fresh:=time.Since(v.refreshed)<5*time.Minute;v.mu.RUnlock();if fresh&&!force{return nil};req,err:=http.NewRequestWithContext(ctx,http.MethodGet,v.jwksURL,nil);if err!=nil{return err};res,err:=v.client.Do(req);if err!=nil{return err};defer res.Body.Close();if res.StatusCode!=200{return errors.New("JWKS unavailable")};var doc jwks;if err:=json.NewDecoder(res.Body).Decode(&doc);err!=nil{return err};keys:=map[string]*rsa.PublicKey{};for _,j:=range doc.Keys{if j.Kty!="RSA"||j.Kid==""{continue};n,e1:=base64.RawURLEncoding.DecodeString(j.N);e,e2:=base64.RawURLEncoding.DecodeString(j.E);if e1!=nil||e2!=nil{continue};ex:=0;for _,b:=range e{ex=ex<<8+int(b)};keys[j.Kid]=&rsa.PublicKey{N:new(big.Int).SetBytes(n),E:ex}};if len(keys)==0{return errors.New("no usable JWKS keys")};v.mu.Lock();v.keys=keys;v.refreshed=time.Now();v.mu.Unlock();return nil}
